const incoming =
  $input.first()?.json ?? {};

const body =
  incoming.body ?? {};

const clean = (value) =>
  String(value ?? '').trim();

const action =
  clean(body.action).toLowerCase();

const opportunityKey =
  clean(body.opportunity_key);

const contactName =
  clean(body.contact_name);

const contactRole =
  clean(body.contact_role);

const contactEmail =
  clean(body.contact_email)
    .toLowerCase();

const contactLinkedinUrl =
  clean(body.contact_linkedin_url);

const allowedActions = [
  'mark_applied',
  'skip',
  'explore_adjacent',
  'explore_speculative',
  'save_manual_contact',
  'move_to_manual_outreach',
];

const errors = [];

if (!allowedActions.includes(action)) {
  errors.push(
    'action must be mark_applied, skip, explore_adjacent, explore_speculative, save_manual_contact, or move_to_manual_outreach.'
  );
}

if (!opportunityKey) {
  errors.push(
    'opportunity_key is required.'
  );
}

if (action === 'save_manual_contact') {
  if (!contactName) {
    errors.push(
      'contact_name is required for a manual contact.'
    );
  }

  if (
    !contactEmail &&
    !contactLinkedinUrl
  ) {
    errors.push(
      'Provide at least a contact email or LinkedIn URL.'
    );
  }

  if (
    contactEmail &&
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
      contactEmail
    )
  ) {
    errors.push(
      'The contact email format is invalid.'
    );
  }

  if (
    contactLinkedinUrl &&
    !contactLinkedinUrl
      .toLowerCase()
      .includes('linkedin.com/')
  ) {
    errors.push(
      'The LinkedIn URL must be a linkedin.com URL.'
    );
  }
}

return [
  {
    json: {
      request_valid:
        errors.length === 0,

      success:
        errors.length === 0,

      http_status:
        errors.length === 0
          ? 200
          : 400,

      errors,
      action,

      opportunity_key:
        opportunityKey,

      contact_name:
        contactName,

      contact_role:
        contactRole,

      contact_email:
        contactEmail,

      contact_linkedin_url:
        contactLinkedinUrl,
    },
  },
];

const request =
  $('Validate Dashboard Action')
    .first()
    .json ?? {};

const clean = (value) =>
  String(value ?? '').trim();

const upper = (value) =>
  clean(value).toUpperCase();

const rows = $input
  .all()
  .map((item) => item.json ?? {})
  .filter((row) =>
    clean(row.opportunity_key)
  );

const requestedKey =
  clean(request.opportunity_key);

const action =
  clean(request.action).toLowerCase();

const manualContactName =
  clean(request.contact_name);

const manualContactRole =
  clean(request.contact_role);

const manualContactEmail =
  clean(request.contact_email)
    .toLowerCase();

const manualLinkedinUrl =
  clean(request.contact_linkedin_url);

const row =
  rows.find(
    (candidate) =>
      clean(candidate.opportunity_key) ===
      requestedKey
  ) ?? null;


function rejected(
  message,
  httpStatus = 409
) {
  return [
    {
      json: {
        can_update: false,
        success: false,
        http_status: httpStatus,
        message,
        action,
        opportunity_key:
          requestedKey,
      },
    },
  ];
}


if (!row) {
  return rejected(
    'The requested opportunity was not found.',
    404
  );
}


const previousStatus =
  upper(row.application_status) ||
  'TO_REVIEW';

const previousOutreachMode =
  upper(row.outreach_mode);

const previousResearchStatus =
  upper(row.contact_research_status) ||
  'NOT_STARTED';

const previousManualContactStatus =
  upper(row.manual_contact_status);

const previousContactSource =
  upper(row.contact_source);

const isManualContactAction =
  action === 'save_manual_contact';

const moveToManualAction =
  action === 'move_to_manual_outreach';


/*
 * Existing tracker rows may not yet have
 * opportunity_type populated, so treat them
 * as normal direct applications by default.
 */
const opportunityType =
  upper(row.opportunity_type) ||
  'DIRECT_APPLICATION';

const isSpeculativeProspect =
  opportunityType ===
  'SPECULATIVE_OUTREACH';


const sentAt =
  clean(row.sent_at);

const outreachStatus =
  upper(row.outreach_status);

const isResearchAction = [
  'explore_adjacent',
  'explore_speculative',
].includes(action);


const hasActiveOutreachStrategy =
  previousStatus === 'APPLIED' ||
  [
    'ADJACENT_ROLE',
    'SPECULATIVE',
  ].includes(
    previousOutreachMode
  );


/*
 * Anything already sent is locked.
 */
if (
  sentAt ||
  outreachStatus === 'SENT'
) {
  return rejected(
    'This opportunity already has sent outreach and cannot be changed.'
  );
}


/*
 * Saving a manual contact is allowed only
 * after an outreach strategy exists.
 */
if (
  isManualContactAction &&
  !hasActiveOutreachStrategy
) {
  return rejected(
    'A manual contact can only be added for an applied, adjacent-role, or speculative outreach opportunity.'
  );
}


const manualPlanBAvailable =
  previousResearchStatus === 'NOT_FOUND' ||
  [
    'NEEDS_CONTACT',
    'CONTACT_ADDED',
  ].includes(
    previousManualContactStatus
  );


if (
  isManualContactAction &&
  !manualPlanBAvailable
) {
  return rejected(
    'Manual contact entry is not currently available for this opportunity.'
  );
}


/*
 * Moving an automatically researched
 * opportunity to Manual Outreach.
 */
if (moveToManualAction) {
  if (!hasActiveOutreachStrategy) {
    return rejected(
      'Manual outreach is only available for an applied, adjacent-role, or speculative opportunity.'
    );
  }

  if (
    previousResearchStatus ===
    'IN_PROGRESS'
  ) {
    return rejected(
      'Contact research is still running. Wait for it to finish before switching to manual outreach.'
    );
  }
}


/*
 * A speculative prospect has no vacancy
 * application, so it cannot be marked applied.
 */
if (
  action === 'mark_applied' &&
  isSpeculativeProspect
) {
  return rejected(
    'A speculative company prospect cannot be marked as applied because there is no direct vacancy.'
  );
}


if (
  action === 'skip' &&
  previousStatus === 'APPLIED'
) {
  return rejected(
    'An applied opportunity cannot be skipped through this action.'
  );
}


/*
 * Adjacent-role outreach belongs only to
 * actual vacancy records.
 */
if (
  action === 'explore_adjacent' &&
  isSpeculativeProspect
) {
  return rejected(
    'This is a speculative company prospect. Use speculative outreach instead.'
  );
}


if (
  action === 'explore_adjacent' &&
  previousStatus === 'APPLIED'
) {
  return rejected(
    'This opportunity is already marked APPLIED. Use post-application outreach instead.'
  );
}


if (
  action === 'explore_adjacent' &&
  previousStatus === 'SKIPPED'
) {
  return rejected(
    'A skipped opportunity must be returned to review before adjacent outreach can start.'
  );
}


/*
 * Speculative outreach is permitted only for
 * records created as SPECULATIVE_OUTREACH.
 */
if (
  action === 'explore_speculative' &&
  !isSpeculativeProspect
) {
  return rejected(
    'Speculative outreach is only available for speculative company prospects.'
  );
}


if (
  action === 'explore_speculative' &&
  previousStatus === 'APPLIED'
) {
  return rejected(
    'An applied vacancy must use post-application outreach instead of speculative outreach.'
  );
}


if (
  action === 'explore_speculative' &&
  previousStatus === 'SKIPPED'
) {
  return rejected(
    'A skipped company prospect must be returned to review before speculative outreach can start.'
  );
}


/*
 * Prevent adjacent/speculative contact
 * research from being started twice.
 */
if (
  isResearchAction &&
  [
    'IN_PROGRESS',
    'COMPLETED',
  ].includes(
    previousResearchStatus
  )
) {
  return rejected(
    'Contact research has already started or completed for this opportunity.'
  );
}


const now =
  new Date().toISOString();


let applicationStatus =
  previousStatus;

let outreachMode =
  previousOutreachMode;

let appliedAt =
  clean(row.applied_at);

let contactResearchStatus =
  previousResearchStatus;

let contactName =
  clean(row.contact_name);

let contactRole =
  clean(row.contact_role);

let contactEmail =
  clean(row.contact_email);

let contactLinkedinUrl =
  clean(row.contact_linkedin_url);

let contactEmailConfidence =
  upper(
    row.contact_email_confidence
  );

let outreachChannel =
  upper(row.outreach_channel);

let contactSource =
  previousContactSource;

let manualContactStatus =
  previousManualContactStatus;

let emailSubject =
  clean(row.email_subject);

let emailDraft =
  clean(row.email_draft);

let linkedinConnectionNote =
  clean(row.linkedin_connection_note);

let linkedinMessage =
  clean(row.linkedin_message);

let draftFinalStatus =
  upper(row.draft_final_status);

let draftGeneratedAt =
  clean(row.draft_generated_at);

let outreachApproval =
  upper(row.outreach_approval) ||
  'PENDING';

let mutableOutreachStatus =
  upper(row.outreach_status) ||
  'NOT_STARTED';

/*
 * Mark normal vacancy as applied.
 */
if (
  action === 'mark_applied'
) {
  applicationStatus =
    'APPLIED';

  outreachMode =
    'POST_APPLICATION';

  appliedAt =
    appliedAt || now;

  if (!contactResearchStatus) {
    contactResearchStatus =
      'NOT_STARTED';
  }
}


/*
 * Skip opportunity.
 */
if (
  action === 'skip'
) {
  applicationStatus =
    'SKIPPED';
}


/*
 * Adjacent-role research.
 */
if (
  action === 'explore_adjacent'
) {
  outreachMode =
    'ADJACENT_ROLE';

  contactResearchStatus =
    'NOT_STARTED';
}


/*
 * Speculative company research.
 * application_status remains TO_REVIEW.
 */
if (
  action === 'explore_speculative'
) {
  outreachMode =
    'SPECULATIVE';

  contactResearchStatus =
    'NOT_STARTED';
}


/*
 * Move an existing automated result to
 * the Manual Outreach page.
 *
 * We deliberately keep the existing
 * automatically discovered contact data
 * so you can use it as reference.
 */
if (
  action === 'move_to_manual_outreach'
) {
  manualContactStatus =
    'NEEDS_CONTACT';
}


/*
 * Save the contact that you found manually.
 */
if (
  action === 'save_manual_contact'
) {
  contactName =
    manualContactName;

  contactRole =
    manualContactRole;

  contactEmail =
    manualContactEmail;

  contactLinkedinUrl =
    manualLinkedinUrl;

  contactSource =
    'MANUAL';

  manualContactStatus =
    'CONTACT_ADDED';

  /*
   * USER_VERIFIED means that you personally
   * found and confirmed this email address.
   */
  contactEmailConfidence =
    contactEmail
      ? 'USER_VERIFIED'
      : '';

  if (
    contactEmail &&
    contactLinkedinUrl
  ) {
    outreachChannel =
      'EMAIL_AND_LINKEDIN';

  } else if (contactEmail) {
    outreachChannel =
      'EMAIL';

  } else {
    outreachChannel =
      'LINKEDIN';
  }

  /*
   * Reset so Contact Research launches again
   * in MANUAL mode and reuses the existing
   * personalization/drafting pipeline.
   */
  contactResearchStatus =
    'NOT_STARTED';

  /*
 * A new manually supplied contact needs a
 * completely fresh outreach draft. Do not
 * reuse drafts generated for the old
 * automatically selected contact.
 */
emailSubject = '';
emailDraft = '';
linkedinConnectionNote = '';
linkedinMessage = '';

draftFinalStatus = '';
draftGeneratedAt = '';

outreachApproval =
  'PENDING';

mutableOutreachStatus =
  'NOT_STARTED';
}


return [
  {
    json: {
      ...row,

      can_update: true,
      success: true,
      http_status: 200,

      action,

      opportunity_key:
        requestedKey,

      opportunity_type:
        opportunityType,

      previous_status:
        previousStatus,

      previous_outreach_mode:
        previousOutreachMode,

      previous_contact_research_status:
        previousResearchStatus,

      application_status:
        applicationStatus,

      outreach_mode:
        outreachMode,

      applied_at:
        appliedAt,

      contact_research_status:
        contactResearchStatus,

      contact_name:
        contactName,

      contact_role:
        contactRole,

      contact_email:
        contactEmail,

      contact_email_confidence:
        contactEmailConfidence,

      contact_linkedin_url:
        contactLinkedinUrl,

      outreach_channel:
        outreachChannel,

      contact_source:
        contactSource,

      manual_contact_status:
        manualContactStatus,

      last_updated:
        now,

      email_subject:
        emailSubject,

      email_draft:
        emailDraft,

      linkedin_connection_note:
        linkedinConnectionNote,

      linkedin_message:
        linkedinMessage,

      draft_final_status:
        draftFinalStatus,

      draft_generated_at:
        draftGeneratedAt,

      outreach_approval:
        outreachApproval,

      outreach_status:
        mutableOutreachStatus,
    },
  },
];

const update =
  $('Prepare Opportunity Update')
    .first()
    .json ?? {};

const clean = (value) =>
  String(value ?? '').trim();

const upper = (value) =>
  clean(value).toUpperCase();

const opportunityKey =
  clean(update.opportunity_key);

const action =
  clean(update.action).toLowerCase();

const previousStatus =
  upper(update.previous_status);

const contactResearchStatus =
  upper(update.contact_research_status) ||
  'NOT_STARTED';

const isTestOpportunity =
  opportunityKey.startsWith('test::');

const requestedResearch =
  action === 'explore_adjacent' ||
  action === 'explore_speculative' ||
  action === 'save_manual_contact' ||
  (
    action === 'mark_applied' &&
    previousStatus !== 'APPLIED'
  );

const shouldStartContactResearch =
  requestedResearch &&
  contactResearchStatus === 'NOT_STARTED' &&
  !isTestOpportunity;

let launchReason = '';

if (isTestOpportunity) {
  launchReason =
    'Test opportunities cannot launch contact research.';
} else if (!requestedResearch) {
  launchReason =
    'This action does not require new contact research.';
} else if (
  contactResearchStatus !== 'NOT_STARTED'
) {
  launchReason =
    'Contact research has already started or completed.';
} else {
  launchReason =
    'Contact research is ready to start.';
}

return [
  {
    json: {
      ...update,

      should_start_contact_research:
        shouldStartContactResearch,

      contact_research_launch_reason:
        launchReason,

      contact_research_launch_checked_at:
        new Date().toISOString(),
    },
  },
];
